    [5441] = { "Utilise la Foreman's Blackjack sur les péons endormis (ceux avec des « Zzz »). Ils se rendorment ensuite : attends ou cherches-en d'autres.", "Use the Foreman's Blackjack on sleeping peons (the ones showing Zzz). They doze off again later: wait or find others." },
    [5561] = { "Utilise le Kodo Kombobulator sur un kodo vieux ou mourant du Kodo Graveyard : il te suit. Ramène-le à Smeed Scrabblescrew, puis recommence (un seul à la fois).", "Use the Kodo Kombobulator on an aged or dying kodo in the Kodo Graveyard: it follows you. Bring it to Smeed Scrabblescrew, then repeat (one at a time)." },
