    [6134] = { "Pose la Crate of Ghost Magnets au cimetière des Magram : des fantômes apparaissent autour. Pose-la au milieu et tue-les un par un.", "Place the Crate of Ghost Magnets at the Magram burial grounds: ghosts spawn around it. Set it in the middle and kill them one by one." },
    [6382] = { "Choisis une seule des trois cibles (Sharptalon, Ursangous ou Shadumbra) : chacune ouvre sa propre quête de rendu.", "Pick just one of the three targets (Sharptalon, Ursangous or Shadumbra): each opens its own turn-in quest." },
    [6383] = { "Choisis une seule des trois cibles (Sharptalon, Ursangous ou Shadumbra) : chacune ouvre sa propre quête de rendu.", "Pick just one of the three targets (Sharptalon, Ursangous or Shadumbra): each opens its own turn-in quest." },
    [6394] = { "La pioche est posée au sol au fond de la grotte, derrière les Vile Familiars.", "The pick lies on the ground at the back of the cave, past the Vile Familiars." },
