    [8361] = { "Pour utiliser les Wind Stones, il faut porter l'ensemble Twilight Cultist complet (médaillon, robe, capuche), qui tombe sur les cultistes de Silithus.", "Using the Wind Stones requires wearing the full Twilight Cultist set (medallion, robe, cowl), which drops from Silithus cultists." },
    [8365] = { "Les chapeaux tombent sur les pirates Southsea autour de Lost Rigger Cove.", "The hats drop from the Southsea pirates around Lost Rigger Cove." },
    [8460] = { "Les furbolgs Deadwood donnent de la réputation Timbermaw : c'est ce qui rend le tunnel vers Winterspring praticable.", "Deadwood furbolgs give Timbermaw reputation: that's what makes the tunnel to Winterspring usable." },
    [8461] = { "Les furbolgs Deadwood donnent de la réputation Timbermaw : c'est ce qui rend le tunnel vers Winterspring praticable.", "Deadwood furbolgs give Timbermaw reputation: that's what makes the tunnel to Winterspring usable." },
